type projectWhere[Q psql.Filterable] struct {
	ID          psql.WhereMod[Q, string]
	Name        psql.WhereMod[Q, string]
	Description psql.WhereMod[Q, string]
	CreatedAt   psql.WhereMod[Q, time.Time]
	UpdatedAt   psql.WhereMod[Q, time.Time]
	ArchivedAt  psql.WhereNullMod[Q, time.Time]
}

func (projectWhere[Q]) AliasedAs(alias string) projectWhere[Q] {
	return buildProjectWhere[Q](buildProjectColumns(alias))
}

func buildProjectWhere[Q psql.Filterable](cols projectColumns) projectWhere[Q] {
	return projectWhere[Q]{
		ID:          psql.Where[Q, string](cols.ID.Expression),
		Name:        psql.Where[Q, string](cols.Name.Expression),
		Description: psql.Where[Q, string](cols.Description.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:   psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		ArchivedAt:  psql.WhereNull[Q, time.Time](cols.ArchivedAt.Expression),
	}
}

func (o *Project) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AccessKeys":
		rels, ok := retrieved.(AccessKeySlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.AccessKeys = rels
		o.R.Loaded.AccessKeys = true

		return nil
	case "Inventories":
		rels, ok := retrieved.(InventorySlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.Inventories = rels
		o.R.Loaded.Inventories = true

		return nil
	case "ProjectMembers":
		rels, ok := retrieved.(ProjectMemberSlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.ProjectMembers = rels
		o.R.Loaded.ProjectMembers = true

		return nil
	case "Repositories":
		rels, ok := retrieved.(RepositorySlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.Repositories = rels
		o.R.Loaded.Repositories = true

		return nil
	case "TaskRuns":
		rels, ok := retrieved.(TaskRunSlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.TaskRuns = rels
		o.R.Loaded.TaskRuns = true

		return nil
	case "TaskTemplates":
		rels, ok := retrieved.(TaskTemplateSlice)
		if !ok {
			return fmt.Errorf("project cannot load %T as %q", retrieved, name)
		}

		o.R.TaskTemplates = rels
		o.R.Loaded.TaskTemplates = true

		return nil
	default:
		return fmt.Errorf("project has no relationship %q", name)
	}
}

