func (os ProjectSlice) LoadAccessKeys(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accessKeys, err := os.AccessKeys(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AccessKeys = nil
		o.R.Loaded.AccessKeys = true
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range accessKeys {

			if !(o.ID == rel.ProjectID) {
				continue
			}

			o.R.AccessKeys = append(o.R.AccessKeys, rel)
		}
	}

	return nil
}

