type projectCountThenLoader[Q orm.Loadable] struct {
	AccessKeys     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Inventories    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ProjectMembers func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Repositories   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	TaskRuns       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	TaskTemplates  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildProjectCountThenLoader[Q orm.Loadable]() projectCountThenLoader[Q] {
	type AccessKeysCountInterface interface {
		LoadCountAccessKeys(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type InventoriesCountInterface interface {
		LoadCountInventories(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ProjectMembersCountInterface interface {
		LoadCountProjectMembers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RepositoriesCountInterface interface {
		LoadCountRepositories(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type TaskRunsCountInterface interface {
		LoadCountTaskRuns(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type TaskTemplatesCountInterface interface {
		LoadCountTaskTemplates(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return projectCountThenLoader[Q]{
		AccessKeys: countThenLoadBuilder[Q](
			"AccessKeys",
			func(ctx context.Context, exec bob.Executor, retrieved AccessKeysCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAccessKeys(ctx, exec, mods...)
			},
		),
		Inventories: countThenLoadBuilder[Q](
			"Inventories",
			func(ctx context.Context, exec bob.Executor, retrieved InventoriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountInventories(ctx, exec, mods...)
			},
		),
		ProjectMembers: countThenLoadBuilder[Q](
			"ProjectMembers",
			func(ctx context.Context, exec bob.Executor, retrieved ProjectMembersCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountProjectMembers(ctx, exec, mods...)
			},
		),
		Repositories: countThenLoadBuilder[Q](
			"Repositories",
			func(ctx context.Context, exec bob.Executor, retrieved RepositoriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountRepositories(ctx, exec, mods...)
			},
		),
		TaskRuns: countThenLoadBuilder[Q](
			"TaskRuns",
			func(ctx context.Context, exec bob.Executor, retrieved TaskRunsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountTaskRuns(ctx, exec, mods...)
			},
		),
		TaskTemplates: countThenLoadBuilder[Q](
			"TaskTemplates",
			func(ctx context.Context, exec bob.Executor, retrieved TaskTemplatesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountTaskTemplates(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountAccessKeys loads the count of AccessKeys into the C struct
func (o *Project) LoadCountAccessKeys(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.AccessKeys(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.AccessKeys = &count
	return nil
}

// LoadCountAccessKeys loads the count of AccessKeys for a slice in a single batch query
func (os ProjectSlice) LoadCountAccessKeys(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[string], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Select(sm.Columns(
		psql.F("unnest", psql.Cast(psql.Arg(pkID), "text[]")),
	))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			AccessKeys.Columns.ProjectID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(AccessKeys.NameAsExpr()),

		// WHERE fk IN (parent PKs)
		sm.Where(AccessKeys.Columns.ProjectID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(AccessKeys.Columns.ProjectID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.AccessKeys = &count
	}

	return nil
}

